import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Goftego: Chat en Tiempo Real, a Un Comando de Distancia","description":"La historia de construir Goftego — una plataforma de chat self-hosted con canales en tiempo real, presencia e indicadores de escritura en un solo archivo SQLite.","frontmatter":{"title":"Goftego: Chat en Tiempo Real, a Un Comando de Distancia","description":"La historia de construir Goftego — una plataforma de chat self-hosted con canales en tiempo real, presencia e indicadores de escritura en un solo archivo SQLite."},"headers":[],"relativePath":"es/vibe-stories/story-4/index.md","filePath":"es/vibe-stories/story-4/index.md"}`),a={name:`es/vibe-stories/story-4/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="goftego-chat-en-tiempo-real-a-un-comando-de-distancia" tabindex="-1">Goftego: Chat en Tiempo Real, a Un Comando de Distancia <a class="header-anchor" href="#goftego-chat-en-tiempo-real-a-un-comando-de-distancia" aria-label="Permalink to “Goftego: Chat en Tiempo Real, a Un Comando de Distancia”">​</a></h1><p>El SaaS de chat alojado encierra a tu comunidad detrás del almacenamiento, los precios y la jurisdicción de otra persona. Para equipos pequeños que solo quieren una sala, el intercambio es absurdo: tus conversaciones, su base de datos. <strong>Goftego</strong> (<a href="https://github.com/Godde3s/goftego" target="_blank" rel="noreferrer">GitHub</a>) — <em>goftego</em> significa &quot;conversación&quot; — es mi respuesta: una plataforma de chat moderna que hospedas tú, en un solo comando.</p><h2 id="la-apuesta-del-archivo-unico" tabindex="-1">La apuesta del archivo único <a class="header-anchor" href="#la-apuesta-del-archivo-unico" aria-label="Permalink to “La apuesta del archivo único”">​</a></h2><p>Todo el estado de un despliegue vive en <strong>un solo archivo SQLite</strong> con modo WAL. Ni un servidor de base de datos que cuidar, ni servicios externos de los que depender. Backup es <code>cp</code>; migración es mover el archivo. Esa única restricción moldeó todo lo demás: forzó consultas eficientes, un diseño cuidadoso de transacciones y una historia de despliegue que es literalmente <code>docker compose up</code>.</p><h2 id="el-tiempo-real-es-una-caracteristica-de-producto-no-un-checkbox" tabindex="-1">El tiempo real es una característica de producto, no un checkbox <a class="header-anchor" href="#el-tiempo-real-es-una-caracteristica-de-producto-no-un-checkbox" aria-label="Permalink to “El tiempo real es una característica de producto, no un checkbox”">​</a></h2><ul><li><strong>Fan-out por WebSocket</strong> — los mensajes de canal llegan a cada suscriptor sin polling, con conteos de presencia e indicadores de escritura que hacen que la sala se sienta viva.</li><li><strong>Auth que respeta los datos</strong> — hashing de contraseñas con bcrypt (coste 12) y sesiones JWT, porque &quot;self-hosted&quot; no puede significar &quot;inseguro&quot;.</li><li><strong>Una UI para humanos</strong> — una SPA en Vue 3, oscura por defecto, bilingüe persa/inglés con RTL correcto. Para un equipo de habla persa, una interfaz que se lee correctamente no es un lujo.</li></ul><h2 id="lo-que-demuestra" tabindex="-1">Lo que demuestra <a class="header-anchor" href="#lo-que-demuestra" aria-label="Permalink to “Lo que demuestra”">​</a></h2><p>Goftego es trabajo de producto full-stack: diseño de protocolos en tiempo real en el backend, gestión de estado en el frontend, y un modelo de datos con opiniones debajo. Demuestra que puedo llevar un producto desde &quot;no estaría mal&quot; hasta <code>docker compose up</code> — y que aplico a usuarios self-hosted la misma barra de seguridad que a un SaaS público. Los datos de tu comunidad se quedan en tu máquina, donde les corresponde.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};